import React, { useEffect } from 'react';

import Preloader from '../components/Miscellaneous/Preloader';
import Header from '../components/Header/Header';
import Hero from '../components/Hero/Hero';

import BreadcrumbTwo from '../components/Breadcrumb/BreadcrumbTwo';
import PortfolioTwo from '../components/Portfolio/PortfolioTwo';

import BreadcrumbOne from '../components/Breadcrumb/BreadcrumbOne';
import AboutSection from '../components/About/AboutSection';
import Process from '../components/Process/Process';
import Experiences from '../components/Experiences/Experiences';
import AnimatedImage from '../components/AnimatedImage/AnimatedImage';
import Skills from '../components/Skills/Skills';
import FAQ from '../components/FAQ/FAQ';

import BreadcrumbAI from '../components/Breadcrumb/BreadcrumbAI';
import AIWorkflowLoop from '../components/AITools/AIWorkflowLoop';
import AIToolStack from '../components/AITools/AIToolStack';

import BreadcrumbThree from '../components/Breadcrumb/BreadcrumbThree';
import Form from '../components/Form/Form';

import Shape from '../components/Shape/Shape';
import Awards from '../components/Awards/AwardsOne';
import CTA from '../components/CTA/CTAOne';
import Footer from '../components/Footer/Footer';
import SearchModal from '../components/Miscellaneous/SearchModal';
import OffcanvasMenu from '../components/Miscellaneous/OffcanvasMenu';
import MagicCursor from '../components/Miscellaneous/MagicCursor';
import LenisScroll from '../components/Header/LenisScroll';
import ScrollToTop from '../components/Miscellaneous/ScrollToTop';
import { scrollToHash } from '../utils/scrollToHash';

const ThemeOne = () => {
	// Handles arriving at "/#works" etc. from a redirected legacy route or a
	// direct link — Lenis and the section layout need a beat to settle first.
	useEffect(() => {
		if (!window.location.hash) return;
		const timer = setTimeout(() => scrollToHash(window.location.hash), 400);
		return () => clearTimeout(timer);
	}, []);

	return (
        <div>
			<ScrollToTop />
			<MagicCursor />
			<Preloader />
			<LenisScroll />
			<div className="main">
				<Header />
				<div id="main-wrapper" className="main-wrapper">
					<Hero />

					{/* Works */}
					<BreadcrumbTwo />
					<PortfolioTwo />

					{/* About */}
					<BreadcrumbOne />
					<AboutSection />
					<Process />
					<Experiences />
					<AnimatedImage imageSrc="/img/case-1.jpg" altText="Project preview" />
					<Skills />
					<FAQ />

					<Shape />

					{/* AI */}
					<BreadcrumbAI />
					<AIWorkflowLoop />
					<AIToolStack />

					<Awards />
					<CTA />

					{/* Contact */}
					<BreadcrumbThree />
					<Form />

					<Footer />
					<SearchModal />
					<OffcanvasMenu />
				</div>
			</div>
		</div>
    );
};

export default ThemeOne;
